-- Columns and primary keys derived from MDAWiki-Legado-Estrutura.sql. Test database only.
CREATE TABLE USUARIOS (ID INTEGER PRIMARY KEY AUTOINCREMENT, EMAIL TEXT NOT NULL UNIQUE, NOME TEXT, SENHA TEXT NOT NULL, SENHA_PROV TEXT, CODIGO_CONTA TEXT, DATA_CODIGO_CONTA TEXT, EMAIL_NOVO TEXT, ATIVO TEXT NOT NULL DEFAULT 'N', APELIDO TEXT, FOTO_64 TEXT, FOTO TEXT, FOTO_32X32_64 TEXT, FOTO_32X32 TEXT, DATA_NASC TEXT, CIDADE TEXT, ESTADO TEXT, CLUBE TEXT, ASSOCIACAO TEXT, TIPO_CLUBE TEXT, BIOGRAFIA TEXT, _ATUALIZ_PG_RELAC TEXT DEFAULT 'S', ENVIA_EMAIL TEXT DEFAULT 'S', FEZ_LOGIN TEXT DEFAULT 'N', NIVEL INTEGER DEFAULT '1', UUID TEXT, DT_ULT_CADASTRO TEXT, QTD_CADASTRADOS INTEGER, DT_ULT_ALTERACAO TEXT, QTD_ALTERADOS INTEGER, DT_ULT_EXCLUSAO TEXT, QTD_APAGADOS INTEGER, DT_ULT_ACESSO TEXT, QTD_ACESSOS INTEGER, NIVEL_ACESSO INTEGER, DT_CADASTRO TEXT, DT_ALTERACAO TEXT);
CREATE TABLE PAGINAS (BUSCA TEXT DEFAULT 'S', NIVEL INTEGER DEFAULT '1', IDENT TEXT NOT NULL, NOME_URL TEXT NOT NULL, NOME TEXT, CONTEUDO_CODE TEXT, CONTEUDO TEXT, CONTEUDO_TXT TEXT, ATUALIZAR TEXT DEFAULT 'N', ACESSOS INTEGER, HTML TEXT DEFAULT 'N', PATROCINADO TEXT DEFAULT 'N', USU_CADASTRO TEXT, DT_CADASTRO TEXT, USU_ALTERACAO TEXT, DT_ALTERACAO TEXT, DT_ATUALIZACAO TEXT, PRIMARY KEY (IDENT));
CREATE TABLE PAGINAS_LOGS (BUSCA TEXT DEFAULT 'S', NIVEL INTEGER DEFAULT '1', NOME_URL_ID INTEGER NOT NULL, IDENT TEXT NOT NULL, NOME_URL TEXT NOT NULL, NOME TEXT, CONTEUDO_CODE TEXT, CONTEUDO TEXT, EMAIL TEXT, ID_USUARIO INTEGER, EXPIRADO TEXT DEFAULT 'N', DATAHORA TEXT, PRIMARY KEY (NOME_URL_ID,IDENT));
CREATE TABLE PAGINAS_CATEGORIAS (IDENT TEXT NOT NULL, NOME_URL TEXT NOT NULL, CATEGORIA TEXT, CATEGORIA_IDENT TEXT NOT NULL, CATEGORIA_URL TEXT NOT NULL, ORDEM INTEGER, PRIMARY KEY (IDENT,CATEGORIA_IDENT));
CREATE TABLE PAGINAS_LINKS (IDENT TEXT NOT NULL DEFAULT '', NOME_URL TEXT NOT NULL DEFAULT '', ID INTEGER NOT NULL, LINK TEXT NOT NULL, LINK_IDENT TEXT NOT NULL, LINK_URL TEXT, LINK_HASH TEXT, LINK_TXT TEXT, PRIMARY KEY (ID,IDENT));
CREATE TABLE PAGINAS_LINKS_EXTERNOS (IDENT TEXT NOT NULL DEFAULT '', NOME_URL TEXT NOT NULL DEFAULT '', ID INTEGER NOT NULL, LINK_URL TEXT NOT NULL, LINK_TXT TEXT NOT NULL, PRIMARY KEY (ID,IDENT));
CREATE TABLE PAGINAS_REDIRECIONAMENTOS (IDENT TEXT NOT NULL DEFAULT '', NOME_URL TEXT NOT NULL DEFAULT '', ID INTEGER NOT NULL, PAGINA TEXT, PAGINA_IDENT TEXT, PAGINA_URL TEXT NOT NULL, PRIMARY KEY (ID,IDENT));
CREATE TABLE PAGINAS_INCLUDES (IDENT TEXT NOT NULL DEFAULT '', NOME_URL TEXT NOT NULL DEFAULT '', ID INTEGER NOT NULL, PAGINA TEXT, PAGINA_IDENT TEXT, PAGINA_URL TEXT NOT NULL, PAGINA_SEC TEXT NOT NULL, PRIMARY KEY (ID,IDENT));
CREATE TABLE PAGINAS_TEMPLATES (IDENT TEXT NOT NULL DEFAULT '', NOME_URL TEXT NOT NULL DEFAULT '', ID INTEGER NOT NULL, TEMPLATE_TAG TEXT, TEMPLATE TEXT, PRIMARY KEY (ID,IDENT));
CREATE TABLE PAGINAS_SUBTITULOS (IDENT TEXT NOT NULL DEFAULT '', NOME_URL TEXT NOT NULL DEFAULT '', ID INTEGER NOT NULL, SUBTITULO TEXT, SUBTITULO_IDENT TEXT, SUBTITULO_URL TEXT NOT NULL, NIVEL INTEGER NOT NULL, PRIMARY KEY (ID,IDENT));
CREATE TABLE PAGINAS_IMAGENS (IDENT TEXT NOT NULL, NOME_URL TEXT NOT NULL DEFAULT '', ID INTEGER NOT NULL, IMAGEM_IDENT TEXT, IMAGEM TEXT, IMAGEM_URL TEXT NOT NULL, IMAGEM_FILE_URL TEXT NOT NULL, IMAGEM_FILE_MINI_URL TEXT NOT NULL, IMAGEM_FILE_CP_URL TEXT NOT NULL, TEMPLATE TEXT NOT NULL DEFAULT '', PRIMARY KEY (ID,IDENT));
CREATE TABLE PAGINAS_VIDEOS (IDENT TEXT NOT NULL DEFAULT '', NOME_URL TEXT NOT NULL DEFAULT '', ID INTEGER NOT NULL, URL TEXT, MSG_ERRO TEXT, PRIMARY KEY (ID,IDENT));
CREATE TABLE TAGS (ID TEXT NOT NULL DEFAULT '', NOME TEXT, PARAM_CODE TEXT, PARAM_HTML TEXT, FUNCAO TEXT, ORDEM INTEGER, POSICAO TEXT, PRIMARY KEY (ID));
CREATE TABLE PAGINAS_ACESSOS_LOGS_QTD_DIARIO (ID INTEGER PRIMARY KEY AUTOINCREMENT, DATA TEXT, IDENT TEXT NOT NULL, NOME_URL TEXT NOT NULL, QTD_ACESSOS INTEGER, ULT_ATUALIZACAO TEXT, UNIQUE(DATA,NOME_URL));
